            seen[r][c] = 1;
            vector<pair<int, int>> st = {{r, c}};
            vector<int> points;
            while (!st.empty()) {
                auto [x, y] = st.back();
                st.pop_back();
                // offset relative to the first cell, encoded as one int
                points.push_back((x - r) * 2048 + (y - c + 1024));
                for (int k = 0; k < 4; k++) {
                    int a = x + dr[k], b = y + dc[k];
