import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int h = (int) nextLong(), w = (int) nextLong();
        char[][] g = new char[h][];
        for (int i = 0; i < h; i++) g[i] = next().toCharArray();
        boolean[][] seen = new boolean[h][w];
        HashSet<String> shapes = new HashSet<>();
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        int[] stack = new int[h * w];
        for (int r = 0; r < h; r++)
            for (int c = 0; c < w; c++) {
                if (g[r][c] != '1' || seen[r][c]) continue;
                seen[r][c] = true;
                int top = 0;
                stack[top++] = r * w + c;
                ArrayList<Integer> pts = new ArrayList<>();
                while (top > 0) {
                    int cur = stack[--top], x = cur / w, y = cur % w;
                    // offset relative to the first cell, encoded as one int
                    pts.add((x - r) * 2048 + (y - c + 1024));
                    for (int k = 0; k < 4; k++) {
                        int a = x + dr[k], b = y + dc[k];
                        if (a >= 0 && a < h && b >= 0 && b < w && g[a][b] == '1' && !seen[a][b]) {
                            seen[a][b] = true;
                            stack[top++] = a * w + b;
                        }
                    }
                }
                int[] arr = new int[pts.size()];
                for (int i = 0; i < arr.length; i++) arr[i] = pts.get(i);
                Arrays.sort(arr);
                shapes.add(Arrays.toString(arr));
            }
        System.out.println(shapes.size());
    }
}

package main

import (
	"bufio"
	"encoding/binary"
	"fmt"
	"os"
	"slices"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	h, _ := strconv.Atoi(sc.Text())
	sc.Scan()
	w, _ := strconv.Atoi(sc.Text())
	g := make([]string, h)
	for i := range g {
		sc.Scan()
		g[i] = sc.Text()
	}
	seen := make([]bool, h*w)
	shapes := map[string]struct{}{}
	dr := [4]int{1, -1, 0, 0}
	dc := [4]int{0, 0, 1, -1}
	for r := 0; r < h; r++ {
		for c := 0; c < w; c++ {
			if g[r][c] != '1' || seen[r*w+c] {
				continue
			}
			seen[r*w+c] = true
			st := []int{r*w + c}
			var pts []uint32
			for len(st) > 0 {
				cur := st[len(st)-1]
				st = st[:len(st)-1]
				x, y := cur/w, cur%w
				// offset relative to the first cell, encoded as one int
				pts = append(pts, uint32((x-r)*2048+(y-c+1024)))
				for k := 0; k < 4; k++ {
					a, b := x+dr[k], y+dc[k]
					if a >= 0 && a < h && b >= 0 && b < w && g[a][b] == '1' && !seen[a*w+b] {
						seen[a*w+b] = true
						st = append(st, a*w+b)
					}
				}
			}
			slices.Sort(pts)
			key := make([]byte, 0, 4*len(pts))
			for _, p := range pts {
				key = binary.LittleEndian.AppendUint32(key, p)
			}
			shapes[string(key)] = struct{}{}
		}
	}
	fmt.Println(len(shapes))
}
